showResponse:id=>{const p=data.proposals.find(x=>x.id===id);modal('Respuesta '+id,`<p>${p.responded} · ${esc(p.responseRef)}</p>${table(['Prenda','Decisión','Contrapropuesta'],p.answers.map(a=>`<tr><td>${a.code}</td><td>${esc(a.answer)}</td><td>${a.answer==='Contrapropuesta'?money(a.price):'—'}</td></tr>`))}${button('Imprimir respuesta','printResponse',id)}`,null)},
printLiq:id=>printDoc('liq',id),printPay:id=>printDoc('pay',id),printProp:id=>printDoc('prop',id),printResponse:id=>printDoc('response',id),printReceipt:id=>printDoc('receipt',id),printReturn:id=>printDoc('return',id),printPrice:id=>printDoc('price',id),
csv:id=>{const l=data.settlements.find(x=>x.id===id);const rows=[['THERAPY · LIQUIDACIÓN DE PRUEBA',id,l.name],['Código','Descripción','Fecha','Cobrado / ajuste','Base contado / histórica','% proveedor','Importe'],...l.rows.map(r=>[r.code,r.desc,r.date,r.price,r.cashPrice??r.price,r.share,r.amount]),['TOTAL','','','','','',l.total]];csvDownload(rows,id+(l.demo?'_PRUEBA':'')+'.csv')}
