document.addEventListener('click',async e=>{const b=e.target.closest('[data-action]');if(!b)return;e.preventDefault();const name=b.dataset.action,id=b.dataset.id;const keep=['copyMail','acceptAll','downloadReport'];if($('#modal').open&&!keep.includes(name)&&!name.startsWith('print')&&name!=='csv')$('#modal').close();try{await handlers[name]?.(id)}catch(err){toast(err.message)}});
function download(content,name,type){const a=document.createElement('a');a.href=URL.createObjectURL(new Blob(['\ufeff',content],{type}));a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(a.href),5000)}
function printDoc(type,id){let title='',body='',supplierName='';
if(type==='liq'){const l=data.settlements.find(x=>x.id===id);title='Liquidación '+id;supplierName=l.name;body=`<p>Emisión ${l.date} · Período ${l.from} a ${l.to}</p>${rowsLiq(l)}<h2>Total proveedor: ${money(l.total)}</h2><p>Cuenta informada: ${esc(l.bank||'Pendiente')} · Titular: ${esc(l.holder||'Pendiente')}</p><p>Esta planilla documenta la liquidación. No acredita el pago.</p>`}
if(type==='pay'){const p=data.payments.find(x=>x.id===id);title='Registro de pago '+id;supplierName=sp(p.supplier).name;body=`<p>Liquidación: ${p.settlement} · Fecha: ${p.date}</p><h2>${money(p.amount)}</h2><p>Medio: ${esc(p.method)}<br>Referencia: ${esc(p.reference)}</p><p>Registro interno ficticio. No constituye comprobante bancario ni acredita una transferencia real.</p>`}
if(type==='prop'||type==='response'){const p=data.proposals.find(x=>x.id===id);title=(type==='prop'?'Propuesta ':'Respuesta ')+id;supplierName=sp(p.supplier).name;body=`<p>${p.date} · Participación proveedor: ${p.share}%</p>${table(['Código','Prenda','Estado / detalle','Precio',...(type==='response'?['Respuesta']:[])],p.rows.map(r=>{const a=p.answers?.find(x=>x.code===r.code);return `<tr><td>${r.code}</td><td>${esc(r.desc)}<small>${esc(categoryOf(it(r.code)))}</small></td><td>${esc(r.quality)} · ${esc(r.notes)}</td><td>${money(r.price)}</td>${type==='response'?`<td>${esc(a?.answer)} ${a?.answer==='Contrapropuesta'?money(a.price):''}</td>`:''}</tr>`}))}<p>Revisión a los 90 días desde recepción. Descuentos sujetos a consentimiento. La devolución requiere registrar la entrega efectiva.</p>${p.responded?`<p>Respuesta ${p.responded}: ${esc(p.responseRef)}</p>`:''}`}
if(type==='receipt'){const [sid,y]=id.split('|'),s=sp(sid);title='Recepción e inventario · '+y;supplierName=s.name;body=table(['Código','Recepción','Prenda','Estado físico','Precio contado propuesto'],data.items.filter(i=>i.supplier===sid&&(y==='Sin fecha'?!i.received:i.received.startsWith(y))).map(i=>`<tr><td>${i.code}</td><td>${i.received}</td><td>${esc(i.desc)}<small>${esc(ownershipOf(i))} · ${esc(categoryOf(i))}</small></td><td>${esc(i.quality)} · ${esc(i.notes)}</td><td>${money(i.market)}</td></tr>`))}
if(type==='return'){const r=data.returns.find(x=>x.id===id);title='Constancia de devolución '+id;supplierName=sp(r.supplier)?.name||'Therapy · stock propio';body=`<p>Prenda ${r.code} · ${r.date} · ${esc(r.type)}</p><p>Motivo: ${esc(r.reason)}</p><p>Referencia: ${esc(r.reference)}</p>${r.refund!==undefined?'<p>Reintegro al cliente: '+money(r.refund)+'</p>':''}`}
if(type==='price'){const p=data.priceChanges.find(x=>x.id===id);title='Cambio de precio '+id;supplierName=sp(it(p.code).supplier)?.name||'Therapy · stock propio';body=`<p>${p.code} · ${p.date}</p><p>Anterior: ${money(p.old)} · Nuevo: ${money(p.price)}</p><p>Motivo: ${esc(p.reason)}</p><p>${p.consent?'Consentimiento: '+esc(p.consentDate)+' · '+esc(p.consentRef):'Stock propio · cambio de precio interno'}</p>`}
let root=$('#print-root');if(!root){root=document.createElement('section');root.id='print-root';document.body.append(root)}root.innerHTML=`<img class="logo" src="therapy-logo-black.png" alt="Therapy"><h1>${esc(title)}</h1><p>${esc(supplierName)}</p><div class="print-watermark">EJEMPLO / PRUEBA · SIN VALIDEZ COMO COMPROBANTE REAL</div>${body}<footer>Therapy · Recycle and Exorcise · Generado ${today()}</footer>`;window.print()}
try{const old=localStorage.getItem('therapy-consignaciones');if(old){const b=document.createElement('button');b.textContent='Descargar respaldo de la prueba anterior';b.onclick=()=>download(old,'therapy-respaldo-anterior.json','application/json');document.querySelector('.notice').append(b);const hint=document.createElement('p');hint.textContent='Hay datos de la versión anterior en este navegador. Se conservaron allí: descargá el respaldo antes de migrarlos. No se mezclaron automáticamente con la nueva prueba.';document.querySelector('.notice').append(hint)}}catch{}
